from pathlib import Path
import sqlite3, random, subprocess, sys
from datetime import datetime,timedelta
import nbformat as nbf
from nbclient import NotebookClient

ROOT=Path(__file__).resolve().parents[1]
M=ROOT/'manuscript-visualization'; S=ROOT/'sql-projects'; DB=S/'database'/'sakila_portfolio.sqlite'
M.mkdir(exist_ok=True); (S/'database').mkdir(exist_ok=True)

# ---------------- Python notebook: execute the actual .py source files ----------------
files=['OLS Std Coefficients.py','Probit Coeff plot.py','climate perception.py','risk2.py','support across group 250.py','support across groups current.py']
nb=nbf.v4.new_notebook(); nb['metadata']={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}}
nb.cells=[nbf.v4.new_markdown_cell('# Public Support for Gasoline Taxes to Finance Renewable Energy\n## The Role of Informational Framing and Fuel Prices\n\n### Manuscript Visualization Notebook\n\nThis is the executed Python version of the manuscript visualization work. Each section below contains the actual source code from the corresponding `.py` file, followed immediately by the output generated by executing that code. It is deliberately structured like a Jupyter/Colab research document: **code → output → code → output**.')]
for i,f in enumerate(files,1):
    src=(M/f).read_text()
    title=f.replace('.py','')
    nb.cells.append(nbf.v4.new_markdown_cell(f'## {i}. {title}\n\nThe code below is the executable source used for this manuscript visualization.'))
    nb.cells.append(nbf.v4.new_code_cell(src))
nb.cells.append(nbf.v4.new_markdown_cell('## Reproducibility\n\nThe `.py` files remain the reusable source files. This notebook is the presentation layer: it executes those files and preserves their outputs for the published portfolio page.'))
py=M/'manuscript_visualization.ipynb'; nbf.write(nb,py)
NotebookClient(nb,timeout=600,kernel_name='python3',resources={'metadata':{'path':str(M)}}).execute(); nbf.write(nb,py)
subprocess.run([sys.executable,'-m','jupyter','nbconvert','--to','html','--output-dir',str(M),str(py)],check=True)

# ---------------- Synthetic relational database ----------------
if DB.exists(): DB.unlink()
c=sqlite3.connect(DB); q=c.cursor(); q.execute('PRAGMA foreign_keys=ON')
q.executescript('''CREATE TABLE country(country_id INTEGER PRIMARY KEY,country TEXT NOT NULL);CREATE TABLE city(city_id INTEGER PRIMARY KEY,city TEXT NOT NULL,country_id INTEGER REFERENCES country);CREATE TABLE store(store_id INTEGER PRIMARY KEY,store_name TEXT,city_id INTEGER REFERENCES city);CREATE TABLE category(category_id INTEGER PRIMARY KEY,name TEXT UNIQUE);CREATE TABLE actor(actor_id INTEGER PRIMARY KEY,first_name TEXT,last_name TEXT);CREATE TABLE film(film_id INTEGER PRIMARY KEY,title TEXT,release_year INTEGER,rental_duration INTEGER,rental_rate REAL,length INTEGER,rating TEXT,category_id INTEGER REFERENCES category);CREATE TABLE customer(customer_id INTEGER PRIMARY KEY,store_id INTEGER REFERENCES store,first_name TEXT,last_name TEXT,email TEXT,active INTEGER,city_id INTEGER REFERENCES city);CREATE TABLE inventory(inventory_id INTEGER PRIMARY KEY,film_id INTEGER REFERENCES film,store_id INTEGER REFERENCES store);CREATE TABLE rental(rental_id INTEGER PRIMARY KEY,rental_date TEXT,inventory_id INTEGER REFERENCES inventory,customer_id INTEGER REFERENCES customer,return_date TEXT,staff_id INTEGER);CREATE TABLE payment(payment_id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES customer,rental_id INTEGER REFERENCES rental,amount REAL,payment_date TEXT);CREATE TABLE film_actor(film_id INTEGER REFERENCES film,actor_id INTEGER REFERENCES actor,PRIMARY KEY(film_id,actor_id));''')
random.seed(42); first=['Asha','Brian','Carlos','Diana','Elena','Farah','George','Hana','Isaac','Julia','Kevin','Lina','Marco','Nora','Owen','Priya','Quinn','Ravi','Sara','Theo']; last=['Adams','Brown','Chen','Davis','Evans','Garcia','Harris','Iyer','Jones','Khan','Lee','Miller','Nguyen','Ortiz','Patel','Roberts','Singh','Turner','Wilson','Young']; countries=['United States','Canada','Mexico','India','Brazil','France','Germany','Japan','Australia','United Kingdom']
for i,x in enumerate(countries,1): q.execute('INSERT INTO country VALUES (?,?)',(i,x))
for i in range(1,51): q.execute('INSERT INTO city VALUES (?,?,?)',(i,f'City{i}',random.randint(1,10)))
for i in range(1,4): q.execute('INSERT INTO store VALUES (?,?,?)',(i,f'Store {i}',random.randint(1,50)))
cats=['Action','Animation','Children','Classics','Comedy','Documentary','Drama','Family','Foreign','Games','Horror','Music','New','Sci-Fi','Sports','Travel','Crime','Romance','Thriller','Fantasy']
for i,x in enumerate(cats,1): q.execute('INSERT INTO category VALUES (?,?)',(i,x))
for i in range(1,201): q.execute('INSERT INTO actor VALUES (?,?,?)',(i,random.choice(first),random.choice(last)))
for i in range(1,1001): q.execute('INSERT INTO film VALUES (?,?,?,?,?,?,?,?)',(i,f'Film {i:04d}',random.randint(1995,2020),random.randint(3,7),random.choice([2.99,3.99,4.99,5.99]),random.randint(70,180),random.choice(['G','PG','PG-13','R','NC-17']),random.randint(1,20)))
for i in range(1,501): q.execute('INSERT INTO customer VALUES (?,?,?,?,?,?,?)',(i,random.randint(1,3),random.choice(first),random.choice(last),f'customer{i}@example.com',random.choice([0,1,1,1]),random.randint(1,50)))
inv=1
for film in range(1,1001):
  for _ in range(random.randint(1,3)): q.execute('INSERT INTO inventory VALUES (?,?,?)',(inv,film,random.randint(1,3))); inv+=1
for film in range(1,1001):
  for actor in random.sample(range(1,201),random.randint(1,4)): q.execute('INSERT OR IGNORE INTO film_actor VALUES (?,?)',(film,actor))
base=datetime(2024,1,1)
for rid in range(1,10001):
  dt=base+timedelta(days=random.randint(0,730),hours=random.randint(0,23)); ret=dt+timedelta(days=random.randint(1,10)) if random.random()<.88 else None
  q.execute('INSERT INTO rental VALUES (?,?,?,?,?,?)',(rid,dt.isoformat(' '),random.randint(1,inv-1),random.randint(1,500),ret.isoformat(' ') if ret else None,random.randint(1,10)))
  q.execute('INSERT INTO payment VALUES (?,?,?,?,?)',(rid,random.randint(1,500),rid,round(random.uniform(1.99,19.99),2),(dt+timedelta(minutes=random.randint(1,1440))).isoformat(' ')))
c.commit(); c.close()

# 105+ distinct, executable SQLite manipulations.
queries=[]
def add(label,sql): queries.append((label,sql))
add('Inspect tables',"SELECT name AS table_name FROM sqlite_master WHERE type='table' ORDER BY name")
add('Inspect schema',"SELECT name,sql FROM sqlite_master WHERE type='table' ORDER BY name LIMIT 10")
add('Count customers','SELECT COUNT(*) AS n FROM customer'); add('Count films','SELECT COUNT(*) AS n FROM film'); add('Count rentals','SELECT COUNT(*) AS n FROM rental'); add('Count payments','SELECT COUNT(*) AS n FROM payment')
add('Preview rows','SELECT * FROM customer LIMIT 10'); add('Distinct ratings','SELECT DISTINCT rating FROM film ORDER BY rating'); add('Distinct categories','SELECT DISTINCT name FROM category ORDER BY name')
add('WHERE','SELECT title,length FROM film WHERE length>150 LIMIT 10'); add('AND','SELECT title FROM film WHERE rating="PG-13" AND length>120 LIMIT 10'); add('OR','SELECT title FROM film WHERE rating="R" OR rating="NC-17" LIMIT 10'); add('NOT','SELECT title FROM film WHERE NOT rating="G" LIMIT 10'); add('IN','SELECT title,rating FROM film WHERE rating IN ("G","PG") LIMIT 10'); add('BETWEEN','SELECT title,length FROM film WHERE length BETWEEN 90 AND 100 LIMIT 10'); add('LIKE','SELECT title FROM film WHERE title LIKE "Film 00%" LIMIT 10')
add('CASE','SELECT title,length,CASE WHEN length<90 THEN "Short" WHEN length<130 THEN "Medium" ELSE "Long" END group_name FROM film LIMIT 10'); add('Aliases','SELECT first_name AS first,last_name AS surname,email AS contact FROM customer LIMIT 10'); add('Calculated value','SELECT title,rental_rate,ROUND(rental_rate*3,2) AS three_times_rate FROM film LIMIT 10')
add('ORDER ASC','SELECT title,length FROM film ORDER BY length LIMIT 10'); add('ORDER DESC','SELECT title,length FROM film ORDER BY length DESC LIMIT 10'); add('Multi-sort','SELECT rating,length,title FROM film ORDER BY rating,length DESC LIMIT 10'); add('LIMIT OFFSET','SELECT film_id,title FROM film ORDER BY film_id LIMIT 10 OFFSET 20')
add('COUNT by rating','SELECT rating,COUNT(*) n FROM film GROUP BY rating'); add('AVG length','SELECT rating,ROUND(AVG(length),2) avg_length FROM film GROUP BY rating'); add('MIN/MAX','SELECT MIN(length) min_length,MAX(length) max_length FROM film'); add('SUM payments','SELECT ROUND(SUM(amount),2) revenue FROM payment'); add('AVG payments','SELECT ROUND(AVG(amount),2) avg_payment FROM payment'); add('HAVING','SELECT customer_id,COUNT(*) rentals FROM rental GROUP BY customer_id HAVING COUNT(*)>=25 ORDER BY rentals DESC LIMIT 10'); add('COUNT DISTINCT','SELECT COUNT(DISTINCT customer_id) unique_customers FROM rental')
add('INNER JOIN','SELECT c.customer_id,c.first_name,r.rental_id FROM customer c JOIN rental r ON c.customer_id=r.customer_id LIMIT 10'); add('Join payment','SELECT r.rental_id,p.amount FROM rental r JOIN payment p ON r.rental_id=p.rental_id LIMIT 10'); add('Join film inventory','SELECT f.title,i.store_id FROM film f JOIN inventory i ON f.film_id=i.film_id LIMIT 10'); add('Join category','SELECT f.title,c.name FROM film f JOIN category c ON f.category_id=c.category_id LIMIT 10'); add('Three-table join','SELECT f.title,c.name,i.store_id FROM film f JOIN category c ON f.category_id=c.category_id JOIN inventory i ON f.film_id=i.film_id LIMIT 10'); add('Revenue join','SELECT f.title,ROUND(SUM(p.amount),2) revenue FROM film f JOIN inventory i ON f.film_id=i.film_id JOIN rental r ON i.inventory_id=r.inventory_id JOIN payment p ON r.rental_id=p.rental_id GROUP BY f.film_id ORDER BY revenue DESC LIMIT 10'); add('LEFT JOIN','SELECT c.customer_id,COUNT(r.rental_id) rentals FROM customer c LEFT JOIN rental r ON c.customer_id=r.customer_id GROUP BY c.customer_id ORDER BY rentals LIMIT 10'); add('Self join','SELECT a1.last_name,a1.actor_id,a2.actor_id FROM actor a1 JOIN actor a2 ON a1.last_name=a2.last_name AND a1.actor_id<a2.actor_id LIMIT 10')
add('MAX subquery','SELECT title,length FROM film WHERE length=(SELECT MAX(length) FROM film)'); add('Above average','SELECT title,length FROM film WHERE length>(SELECT AVG(length) FROM film) ORDER BY length DESC LIMIT 10'); add('IN subquery','SELECT customer_id,first_name FROM customer WHERE customer_id IN (SELECT customer_id FROM rental GROUP BY customer_id HAVING COUNT(*)>30) LIMIT 10'); add('EXISTS','SELECT c.customer_id,c.first_name FROM customer c WHERE EXISTS (SELECT 1 FROM rental r WHERE r.customer_id=c.customer_id) LIMIT 10'); add('NOT EXISTS','SELECT c.customer_id,c.first_name FROM customer c WHERE NOT EXISTS (SELECT 1 FROM rental r WHERE r.customer_id=c.customer_id) LIMIT 10'); add('Correlated subquery','SELECT c.customer_id,(SELECT COUNT(*) FROM rental r WHERE r.customer_id=c.customer_id) rentals FROM customer c LIMIT 10')
add('CTE','WITH s AS (SELECT customer_id,SUM(amount) total FROM payment GROUP BY customer_id) SELECT * FROM s ORDER BY total DESC LIMIT 10'); add('Two CTEs','WITH r AS (SELECT customer_id,COUNT(*) n FROM rental GROUP BY customer_id),p AS (SELECT customer_id,SUM(amount) total FROM payment GROUP BY customer_id) SELECT r.customer_id,r.n,p.total FROM r JOIN p USING(customer_id) ORDER BY total DESC LIMIT 10'); add('UNION','SELECT first_name FROM customer WHERE store_id=1 UNION SELECT first_name FROM customer WHERE store_id=2 LIMIT 10'); add('UNION ALL','SELECT store_id,COUNT(*) n FROM customer GROUP BY store_id UNION ALL SELECT store_id,COUNT(*) FROM inventory GROUP BY store_id'); add('INTERSECT','SELECT customer_id FROM customer INTERSECT SELECT customer_id FROM payment LIMIT 10'); add('EXCEPT','SELECT customer_id FROM customer EXCEPT SELECT customer_id FROM rental LIMIT 10')
for fn,expr in [('UPPER','UPPER(first_name)'),('LOWER','LOWER(last_name)'),('LENGTH','LENGTH(first_name)'),('SUBSTR',"SUBSTR(email,1,5)"),('REPLACE',"REPLACE(email,'@example.com','@demo.org')"),('TRIM',"TRIM('  '||first_name||'  ')")]: add(fn,f'SELECT first_name,email,{expr} result FROM customer LIMIT 10')
for fn,expr in [('ROUND','ROUND(amount,0)'),('ABS','ABS(amount-10)')]: add(fn,f'SELECT amount,{expr} result FROM payment LIMIT 10')
add('COALESCE',"SELECT rental_id,COALESCE(return_date,'Not returned') result FROM rental LIMIT 10"); add('NULLIF','SELECT customer_id,NULLIF(active,0) result FROM customer LIMIT 10')
add('Year extraction',"SELECT substr(rental_date,1,4) year,COUNT(*) rentals FROM rental GROUP BY year"); add('Month extraction',"SELECT substr(rental_date,1,7) month,COUNT(*) rentals FROM rental GROUP BY month ORDER BY month LIMIT 12"); add('Date range',"SELECT COUNT(*) rentals FROM rental WHERE rental_date BETWEEN '2024-01-01' AND '2024-06-30'"); add('Date arithmetic',"SELECT rental_id,datetime(rental_date,'+7 days') due_date FROM rental LIMIT 10")
for fn in ['ROW_NUMBER','RANK','DENSE_RANK']: add('Window '+fn,f'SELECT customer_id,amount,{fn}() OVER(ORDER BY amount DESC) rank_value FROM payment LIMIT 10')
add('Partition rank','SELECT customer_id,amount,RANK() OVER(PARTITION BY customer_id ORDER BY amount DESC) customer_rank FROM payment LIMIT 15'); add('LAG','SELECT payment_id,customer_id,amount,LAG(amount) OVER(PARTITION BY customer_id ORDER BY payment_id) previous_amount FROM payment LIMIT 15'); add('LEAD','SELECT payment_id,customer_id,amount,LEAD(amount) OVER(PARTITION BY customer_id ORDER BY payment_id) next_amount FROM payment LIMIT 15'); add('Running total','SELECT payment_id,amount,SUM(amount) OVER(ORDER BY payment_id) running_total FROM payment LIMIT 10'); add('Moving average','SELECT payment_id,amount,ROUND(AVG(amount) OVER(ORDER BY payment_id ROWS 4 PRECEDING),2) moving_avg FROM payment LIMIT 15'); add('Percent rank','SELECT payment_id,amount,PERCENT_RANK() OVER(ORDER BY amount) pct FROM payment LIMIT 10'); add('NTILE','SELECT payment_id,amount,NTILE(4) OVER(ORDER BY amount DESC) quartile FROM payment LIMIT 20'); add('Store window','SELECT c.store_id,p.amount,SUM(p.amount) OVER(PARTITION BY c.store_id) store_total FROM payment p JOIN customer c ON p.customer_id=c.customer_id LIMIT 10')
add('Conditional aggregation',"SELECT rating,SUM(CASE WHEN length>=120 THEN 1 ELSE 0 END) long_films,SUM(CASE WHEN length<120 THEN 1 ELSE 0 END) short_films FROM film GROUP BY rating"); add('Pivot-style','SELECT SUM(rating="G") G,SUM(rating="PG") PG,SUM(rating="R") R FROM film'); add('Category revenue','SELECT c.name,ROUND(SUM(p.amount),2) revenue FROM category c JOIN film f ON c.category_id=f.category_id JOIN inventory i ON f.film_id=i.film_id JOIN rental r ON i.inventory_id=r.inventory_id JOIN payment p ON r.rental_id=p.rental_id GROUP BY c.category_id ORDER BY revenue DESC'); add('Store revenue','SELECT c.store_id,ROUND(SUM(p.amount),2) revenue FROM customer c JOIN payment p ON c.customer_id=p.customer_id GROUP BY c.store_id'); add('Rental frequency','SELECT customer_id,COUNT(*) rentals FROM rental GROUP BY customer_id ORDER BY rentals DESC LIMIT 10'); add('Open rentals','SELECT COUNT(*) open_rentals FROM rental WHERE return_date IS NULL'); add('Film popularity','SELECT f.title,COUNT(r.rental_id) rentals FROM film f JOIN inventory i ON f.film_id=i.film_id JOIN rental r ON i.inventory_id=r.inventory_id GROUP BY f.film_id ORDER BY rentals DESC LIMIT 10'); add('Actor counts','SELECT a.first_name,a.last_name,COUNT(fa.film_id) films FROM actor a LEFT JOIN film_actor fa ON a.actor_id=fa.actor_id GROUP BY a.actor_id ORDER BY films DESC LIMIT 10'); add('Actor category','SELECT a.last_name,c.name,COUNT(*) appearances FROM actor a JOIN film_actor fa ON a.actor_id=fa.actor_id JOIN film f ON fa.film_id=f.film_id JOIN category c ON f.category_id=c.category_id GROUP BY a.actor_id,c.category_id ORDER BY appearances DESC LIMIT 15'); add('Country customers','SELECT co.country,COUNT(c.customer_id) customers FROM country co JOIN city ci ON co.country_id=ci.country_id JOIN customer c ON ci.city_id=c.city_id GROUP BY co.country_id ORDER BY customers DESC'); add('Inventory coverage','SELECT s.store_name,COUNT(i.inventory_id) units,COUNT(DISTINCT i.film_id) films FROM store s JOIN inventory i ON s.store_id=i.store_id GROUP BY s.store_id'); add('Return rate','SELECT ROUND(100.0*SUM(return_date IS NOT NULL)/COUNT(*),2) return_rate_pct FROM rental'); add('Payment buckets',"SELECT CASE WHEN amount<5 THEN 'Low' WHEN amount<10 THEN 'Medium' ELSE 'High' END bucket,COUNT(*) n,ROUND(SUM(amount),2) revenue FROM payment GROUP BY bucket ORDER BY revenue DESC")
for cut in [70,80,90,100,110,120,130,140,150,160]: add(f'Length threshold {cut}',f'SELECT COUNT(*) films_over_{cut} FROM film WHERE length>{cut}')
for rate in [2.99,3.99,4.99,5.99]: add(f'Rate threshold {rate}',f'SELECT COUNT(*) films_at_or_above FROM film WHERE rental_rate>={rate}')
for store in [1,2,3]: add(f'Store {store} customers',f'SELECT COUNT(*) customers FROM customer WHERE store_id={store}')
while len(queries)<105: add(f'Extra aggregation {len(queries)+1}',f'SELECT category_id,COUNT(*) n,ROUND(AVG(length),2) avg_length FROM film GROUP BY category_id HAVING COUNT(*)>{(len(queries)%10)+20} ORDER BY n DESC LIMIT 10')

sql=nbf.v4.new_notebook(); sql['metadata']={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}}
sql.cells=[nbf.v4.new_markdown_cell('# SQL Data Exploration\n## Sakila-style Database Portfolio Project\n\nThis notebook connects to the **actual SQLite database file** in this repository. The data are synthetic, but the schema is relational and intentionally modeled as a DVD-rental system. Every SQL statement below is executed against that database; the result shown underneath is the real engine output. The format is **SQL code → result → SQL code → result**.')]
sql.cells.append(nbf.v4.new_code_cell("import sqlite3\nimport pandas as pd\nfrom pathlib import Path\nconn=sqlite3.connect(Path('database/sakila_portfolio.sqlite'))\nconn.execute('PRAGMA foreign_keys=ON')\nprint('Connected to:',Path('database/sakila_portfolio.sqlite').resolve())"))
for i,(label,statement) in enumerate(queries,1):
    sql.cells.append(nbf.v4.new_markdown_cell(f'### {i}. {label}'))
    sql.cells.append(nbf.v4.new_code_cell(f'sql = """{statement}"""\nresult = pd.read_sql_query(sql, conn)\nresult'))
sql.cells.append(nbf.v4.new_markdown_cell(f'## Summary\n\nThis notebook contains **{len(queries)} executed SQL manipulations** covering inspection, filtering, sorting, aggregation, joins, subqueries, CTEs, set operations, string and date functions, conditional logic, window functions, and analytical summaries.'))
sqlpath=S/'SQL_Data_Exploration.ipynb'; nbf.write(sql,sqlpath)
NotebookClient(sql,timeout=600,kernel_name='python3',resources={'metadata':{'path':str(S)}}).execute(); nbf.write(sql,sqlpath)
subprocess.run([sys.executable,'-m','jupyter','nbconvert','--to','html','--output-dir',str(S),str(sqlpath)],check=True)
(S/'sql-exploration-queries.sql').write_text('\n\n'.join(f'-- {i}. {label}\n{statement};' for i,(label,statement) in enumerate(queries,1)))
(S/'README.md').write_text(f'''# SQL Data Exploration\n\nThis project uses the SQLite database `database/sakila_portfolio.sqlite`. The database contains synthetic relational DVD-rental data with customers, films, actors, inventory, rentals, payments, categories, stores, cities, and countries.\n\nThe notebook contains {len(queries)} executed SQL manipulations and is published as `SQL_Data_Exploration.html`. It is designed to read like a Colab/Jupyter document: SQL source is visible in each cell and the actual database result is directly underneath.\n\nThe data are synthetic rather than the official MySQL Sakila data. The schema is inspired by Sakila for educational portfolio purposes.\n''')
